function Mana({value}){if(!value)return <span className="muted">—</span>;return <span className="mana" aria-label={value}>{(value.match(/\{[^}]+\}/g)||[]).map((s,i)=><span key={i} data-color={s.slice(1,-1)}>{s.slice(1,-1)}</span>)}</span>;}
