function Empty({icon='layers',title,children,action}){return <div className="empty"><span className="empty-icon"><Icon name={icon} size={32}/></span><h3>{title}</h3><p>{children}</p>{action}</div>;}
function Modal({title,onClose,children,wide=false}){const ref=useRef();useEffect(()=>{const old=document.activeElement;ref.current?.focus();const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const focusable=Array.from(ref.current?.querySelectorAll('button,input,select,textarea,a[href],audio')||[]).filter(x=>!x.disabled);const a=focusable[0],z=focusable.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();z?.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a?.focus();}}};document.addEventListener('keydown',key);document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow='';old?.focus();};},[]);return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)onClose();}}><section className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><header><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><Icon name="close"/></button></header>{children}</section></div>;}
function useSearch(query,filters={},enabled=true){const [retryVersion,retrySearch]=useState(0);const [data,setData]=useState({cards:[],total:0}),[loading,setLoading]=useState(false),[error,setError]=useState('');const serialized=JSON.stringify(filters);useEffect(()=>{if(!enabled){setData({cards:[],total:0});return;}const controller=new AbortController(),timer=setTimeout(async()=>{setLoading(true);setError('');setData({cards:[],total:0});try{const params=new URLSearchParams({q:query,...filters});const response=await cardRequest('/api/cards?'+params,{signal:controller.signal});if(!response.ok)throw Error('Card search could not complete.');setData(await response.json());}catch(e){if(e.name!=='AbortError')setError(e.message);}finally{if(!controller.signal.aborted)setLoading(false);}},150);return()=>{clearTimeout(timer);controller.abort();};},[query,serialized,enabled,retryVersion]);return {...data,loading,error,retry:()=>retrySearch(v=>v+1)};}
function CardPicker({onPick,placeholder='Type a card name…',label='Card name',commander=false}){const [query,setQuery]=useState('');const {cards,loading,error,retry}=useSearch(query,{limit:6,...(commander?{commander:'true'}:{})},query.trim().length>=2);return <div className="picker"><label>{label}<div className="input-icon"><Icon name="search"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={placeholder} autoComplete="off" aria-label={label}/>{loading&&<span className="spinner"/>}</div></label>{error&&<div role="alert"><p className="error">{error}</p><Button variant="outline small" onClick={retry}>Retry card search</Button></div>}{query.length>=2&&<div className="picker-results">{cards.map(card=><button type="button" key={card.id} onClick={()=>{onPick(card);setQuery('');}}><span><strong>{card.name}</strong><small>{card.typeLine}</small></span><Mana value={card.manaCost}/></button>)}{!loading&&!cards.length&&<p>No matches. Try another name.</p>}</div>}</div>;}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function Panel({title,children,action,className=''}){return <section className={'panel '+className}>{title&&<div className="panel-heading"><h3>{title}</h3>{action}</div>}{children}</section>;}
function Bullets({items=[]}){return <ul className="insights">{items.filter(Boolean).map((item,i)=><li key={i}>{typeof item==='string'?item:JSON.stringify(item)}</li>)}</ul>;}
class Boundary extends React.Component{constructor(p){super(p);this.state={error:null};}static getDerivedStateFromError(error){return {error};}render(){return this.state.error?<div className="fatal"><h1>This view needs a refresh.</h1><p>{this.state.error.message}</p><Button onClick={()=>{location.hash='#/home';location.reload();}}>Return home</Button></div>:this.props.children;}}

